package dev.jarofcucumbers.prscraft.client;
import dev.jarofcucumbers.prscraft.*;
import net.minecraft.core.BlockPos;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.gui.components.EditBox;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.chat.Component;
public final class OrthogonalityScreen extends PanelScreen{
    private final BlockPos pos;private CompoundTag data;private EditBox start,end,tolerance,rate;private boolean discrete;private int ticks;private String error="";
    public OrthogonalityScreen(BlockPos pos,CompoundTag data){super(Component.translatable("block.prscraft.orthogonality_meter"),760,500);this.pos=pos;this.data=data;discrete=data.getCompound("orthogonality").getBoolean("discrete");}public BlockPos pos(){return pos;}public void receive(CompoundTag next){data=next;error=next.getString("error");}
    @Override protected void build(){var cfg=OrthogonalitySettings.read(data.getCompound("orthogonality"));start=field(14,68,170,start==null?Double.toString(cfg.start()):start.getValue(),18,"window_start");end=field(200,68,170,end==null?Double.toString(cfg.end()):end.getValue(),18,"window_end");tolerance=field(386,68,170,tolerance==null?Double.toString(cfg.tolerance()):tolerance.getValue(),18,"orthogonal_tolerance");rate=field(572,68,174,rate==null?Double.toString(cfg.sampleHz()):rate.getValue(),18,"orthogonal_rate");button(14,112,240,tr(discrete?"orthogonal_discrete":"orthogonal_continuous"),b->{discrete=!discrete;b.setMessage(tr(discrete?"orthogonal_discrete":"orthogonal_continuous"));});button(270,112,220,tr("apply"),b->{try{var next=new OrthogonalitySettings(number(start),number(end),number(tolerance),discrete,number(rate));var t=data.getCompound("settings").copy();t.put("orthogonality",next.save());RadioClient.request(new RadioNetwork.Request(pos,true,t));}catch(IllegalArgumentException e){error=e.getMessage();}});button(506,112,240,tr("media"),b->{var t=new CompoundTag();t.putString("action","media");RadioClient.request(new RadioNetwork.Request(pos,false,t));});button(14,450,220,tr("back"),b->onClose());button(252,450,240,tr("oscilloscope"),b->minecraft.setScreen(new PlotScreen(this,data)));button(506,450,240,tr("book"),b->minecraft.setScreen(new HandbookScreen(this)));if(data.getBoolean("recorded")||data.getBoolean("analysis"))for(var widget:renderables)if(widget instanceof net.minecraft.client.gui.components.AbstractWidget w&&w.getY()<200)w.active=false;}
    @Override protected void draw(GuiGraphics g){String[] keys={"window_start","window_end","orthogonal_tolerance","orthogonal_rate"};for(int i=0;i<4;i++)label(g,keys[i],14+i*186,48);var r=data.getCompound("orthogonalityResult");g.drawString(font,tr(!r.getBoolean("valid")?"orthogonal_invalid":r.getBoolean("orthogonal")?"orthogonal_yes":"orthogonal_no"),14,178,r.getBoolean("orthogonal")?0xff91e5b5:0xffe9c387,false);g.drawString(font,"<A,B>="+fmt(r.getDouble("inner"))+" · ρ="+fmt(r.getDouble("rho")),14,216,0xffd4e8e2,false);g.drawString(font,"EA="+fmt(r.getDouble("energyA"))+" · EB="+fmt(r.getDouble("energyB"))+" · N="+r.getInt("count")+" · end="+fmt(r.getDouble("end")),14,252,0xffd4e8e2,false);g.drawWordWrap(font,tr("orthogonal_help"),14,294,732,0xffa9cadb);if(!error.isEmpty())g.drawString(font,Component.translatable("error.prscraft."+error),14,408,0xffffae7d,false);else if(!data.getString("fault").isEmpty())g.drawString(font,Component.translatable("fault.prscraft."+data.getString("fault")),14,408,0xffffae7d,false);}
    @Override public void tick(){if(data.getBoolean("recorded")||data.getBoolean("analysis"))return;if(!RadioClient.inRange(pos)){onClose();return;}if(++ticks%20==0)RadioClient.request(new RadioNetwork.Request(pos,false,new CompoundTag()));}
    @Override public void onClose(){RadioClient.closeDevice(null);}
}
